// Two pointers: find two values with a target sum (exercise 1)
function twoPointersFindTwoValuesWithATargetSum1(values, target) {
  let left = 0;
  let right = values.length - 1;
  while (left < right) {
    const sum = values[left] + values[right];
    if (sum === target) return [left, right];
    if (sum < target) left += 1;
    else right -= 1;
  }
  return [];
}

