// Breadth-first search: find the shortest grid path (exercise 1)
function breadthFirstSearchFindTheShortestGridPath1(graph, source, target) {
  const queue = [source];
  const distance = new Map([[source, 0]]);
  for (let head = 0; head < queue.length; head += 1) {
    const node = queue[head];
    if (node === target) return distance.get(node);
    for (const next of graph.get(node) ?? []) {
      if (!distance.has(next)) {
        distance.set(next, distance.get(node) + 1);
        queue.push(next);
      }
    }
  }
  return -1;
}

