// Union find: merge customer accounts (exercise 1)
function unionFindMergeCustomerAccounts1(size, edges) {
  const parent = Array.from({ length: size }, (_, index) => index);
  const find = (node) => parent[node] === node ? node : (parent[node] = find(parent[node]));
  for (const [left, right] of edges) {
    const rootLeft = find(left);
    const rootRight = find(right);
    if (rootLeft !== rootRight) parent[rootLeft] = rootRight;
  }
  return new Set(parent.map(find)).size;
}

