// Sliding window: find the longest unique substring (exercise 1)
function slidingWindowFindTheLongestUniqueSubstring1(text) {
  const seen = new Map();
  let start = 0;
  let best = 0;
  for (let end = 0; end < text.length; end += 1) {
    const previous = seen.get(text[end]);
    if (previous !== undefined && previous >= start) start = previous + 1;
    seen.set(text[end], end);
    best = Math.max(best, end - start + 1);
  }
  return best;
}

