// Dynamic programming: solve zero-one knapsack (exercise 1)
function dynamicProgrammingSolveZeroOneKnapsack1(weights, values, capacity) {
  const dp = Array(capacity + 1).fill(0);
  for (let item = 0; item < weights.length; item += 1) {
    for (let room = capacity; room >= weights[item]; room -= 1) {
      dp[room] = Math.max(dp[room], dp[room - weights[item]] + values[item]);
    }
  }
  return dp[capacity];
}

