# Sliding window: find the longest unique substring (exercise 1)
def slidingWindowFindTheLongestUniqueSubstring1(text):
    seen = {}
    start = best = 0
    for end, character in enumerate(text):
        if character in seen and seen[character] >= start:
            start = seen[character] + 1
        seen[character] = end
        best = max(best, end - start + 1)
    return best

