# Breadth-first search: find the shortest grid path (exercise 1)
def breadthFirstSearchFindTheShortestGridPath1(graph, source, target):
    queue = [source]
    distance = {source: 0}
    for node in queue:
        if node == target:
            return distance[node]
        for next_node in graph.get(node, []):
            if next_node not in distance:
                distance[next_node] = distance[node] + 1
                queue.append(next_node)
    return -1

