# Dynamic programming: solve zero-one knapsack (exercise 1)
def dynamicProgrammingSolveZeroOneKnapsack1(weights, values, capacity):
    dp = [0] * (capacity + 1)
    for weight, value in zip(weights, values):
        for room in range(capacity, weight - 1, -1):
            dp[room] = max(dp[room], dp[room - weight] + value)
    return dp[capacity]

