public static int BinarySearchFindAnExactOrderId1(int[] values, int target) {
  int left = 0;
  int right = values.length - 1;
  while (left <= right) {
    int middle = left + (right - left) / 2;
    if (values[middle] == target) return middle;
    if (values[middle] < target) left = middle + 1;
    else right = middle - 1;
  }
