// Sliding window: find the longest unique substring (exercise 1)
public static int SlidingWindowFindTheLongestUniqueSubstring1(String text) {
  Map<Character, Integer> seen = new HashMap<>();
  int start = 0, best = 0;
  for (int end = 0; end < text.length(); end++) {
    char character = text.charAt(end);
    Integer previous = seen.get(character);
    if (previous != null && previous >= start) start = previous + 1;
    seen.put(character, end);
    best = Math.max(best, end - start + 1);
  }
  return best;
}

