// Breadth-first search: find the shortest grid path (exercise 1)
public static int BreadthFirstSearchFindTheShortestGridPath1(Map<Integer, List<Integer>> graph, int source, int target) {
  Queue<Integer> queue = new ArrayDeque<>();
  Map<Integer, Integer> distance = new HashMap<>();
  queue.add(source);
  distance.put(source, 0);
  while (!queue.isEmpty()) {
    int node = queue.remove();
    if (node == target) return distance.get(node);
    for (int next : graph.getOrDefault(node, List.of())) {
      if (!distance.containsKey(next)) { distance.put(next, distance.get(node) + 1); queue.add(next); }
    }
  }
  return -1;
}

