// Dynamic programming: solve zero-one knapsack (exercise 1)
public static int DynamicProgrammingSolveZeroOneKnapsack1(int[] weights, int[] values, int capacity) {
  int[] dp = new int[capacity + 1];
  for (int item = 0; item < weights.length; item++) {
    for (int room = capacity; room >= weights[item]; room--) {
      dp[room] = Math.max(dp[room], dp[room - weights[item]] + values[item]);
    }
  }
  return dp[capacity];
}

