// Union find: merge customer accounts (exercise 1)
public static int UnionFindMergeCustomerAccounts1(int size, int[][] edges) {
  int[] parent = IntStream.range(0, size).toArray();
  for (int[] edge : edges) {
    int left = edge[0], right = edge[1];
    while (parent[left] != left) { parent[left] = parent[parent[left]]; left = parent[left]; }
    while (parent[right] != right) { parent[right] = parent[parent[right]]; right = parent[right]; }
    if (left != right) parent[left] = right;
  }
  Set<Integer> groups = new HashSet<>();
  for (int node = 0; node < size; node++) { while (parent[node] != node) node = parent[node]; groups.add(node); }
  return groups.size();
}

