// Sliding window: find the longest unique substring (exercise 1)
func slidingWindowFindTheLongestUniqueSubstring1(text string) int {
	seen := map[rune]int{}
	start, best := 0, 0
	for end, character := range []rune(text) {
		if previous, ok := seen[character]; ok && previous >= start { start = previous + 1 }
		seen[character] = end
		if end-start+1 > best { best = end - start + 1 }
	}
	return best
}

