// Breadth-first search: find the shortest grid path (exercise 1)
func breadthFirstSearchFindTheShortestGridPath1(graph map[int][]int, source, target int) int {
	queue := []int{source}
	distance := map[int]int{source: 0}
	for head := 0; head < len(queue); head++ {
		node := queue[head]
		if node == target { return distance[node] }
		for _, next := range graph[node] {
			if _, seen := distance[next]; !seen { distance[next] = distance[node] + 1; queue = append(queue, next) }
		}
	}
	return -1
}

