// Dynamic programming: solve zero-one knapsack (exercise 1)
func dynamicProgrammingSolveZeroOneKnapsack1(weights, values []int, capacity int) int {
	dp := make([]int, capacity+1)
	for item, weight := range weights {
		for room := capacity; room >= weight; room-- {
			candidate := dp[room-weight] + values[item]
			if candidate > dp[room] { dp[room] = candidate }
		}
	}
	return dp[capacity]
}

