// Union find: merge customer accounts (exercise 1)
func unionFindMergeCustomerAccounts1(size int, edges [][2]int) int {
	parent := make([]int, size)
	for index := range parent { parent[index] = index }
	var find func(int) int
	find = func(node int) int { if parent[node] != node { parent[node] = find(parent[node]) }; return parent[node] }
	for _, edge := range edges { left, right := find(edge[0]), find(edge[1]); if left != right { parent[left] = right } }
	groups := map[int]bool{}
	for node := range parent { groups[find(node)] = true }
	return len(groups)
}

