// Order management: create an idempotent checkout order (exercise 1)
func orderManagementCreateAnIdempotentCheckoutOrder1(ctx context.Context, input Request, services Services) (Record, error) {
	existing, err := services.Orders.FindByID(ctx, input.ID)
	if err != nil { return Record{}, err }
	if existing.Status == "completed" { return existing, nil }
	validated, err := services.Validation.Validate(ctx, input)
	if err != nil { return Record{}, err }
	result, err := services.Orders.CreateOrUpdate(ctx, validated, existing)
	if err != nil { return Record{}, err }
	return result, services.Outbox.Publish(ctx, "order.changed", result.ID)
}

