// Binary search: find an exact order id (exercise 1)
fn binarySearchFindAnExactOrderId1(values: &[i32], target: i32) -> i32 {
    let (mut left, mut right) = (0_i32, values.len() as i32 - 1);
    while left <= right {
        let middle = left + (right - left) / 2;
        let value = values[middle as usize];
        if value == target { return middle; }
        if value < target { left = middle + 1; } else { right = middle - 1; }
    }
    -1
}

