// Sliding window: find the longest unique substring (exercise 1)
fn slidingWindowFindTheLongestUniqueSubstring1(text: &str) -> usize {
    use std::collections::HashMap;
    let mut seen = HashMap::new();
    let (mut start, mut best) = (0, 0);
    for (end, character) in text.chars().enumerate() {
        if let Some(&previous) = seen.get(&character) { start = start.max(previous + 1); }
        seen.insert(character, end);
        best = best.max(end - start + 1);
    }
    best
}

