// Breadth-first search: find the shortest grid path (exercise 1)
fn breadthFirstSearchFindTheShortestGridPath1(graph: &[Vec<usize>], source: usize, target: usize) -> i32 {
    use std::collections::VecDeque;
    let mut queue = VecDeque::from([source]);
    let mut distance = vec![-1; graph.len()];
    distance[source] = 0;
    while let Some(node) = queue.pop_front() {
        if node == target { return distance[node]; }
        for &next in &graph[node] {
            if distance[next] < 0 { distance[next] = distance[node] + 1; queue.push_back(next); }
        }
    }
    -1
}

