// Dynamic programming: solve zero-one knapsack (exercise 1)
fn dynamicProgrammingSolveZeroOneKnapsack1(weights: &[usize], values: &[i32], capacity: usize) -> i32 {
    let mut dp = vec![0; capacity + 1];
    for (&weight, &value) in weights.iter().zip(values) {
        for room in (weight..=capacity).rev() {
            dp[room] = dp[room].max(dp[room - weight] + value);
        }
    }
    dp[capacity]
}

