// Union find: merge customer accounts (exercise 1)
fn unionFindMergeCustomerAccounts1(size: usize, edges: &[(usize, usize)]) -> usize {
    fn find(parent: &mut [usize], node: usize) -> usize {
        if parent[node] != node { parent[node] = find(parent, parent[node]); }
        parent[node]
    }
    let mut parent: Vec<usize> = (0..size).collect();
    for &(left, right) in edges { let a = find(&mut parent, left); let b = find(&mut parent, right); if a != b { parent[a] = b; } }
    (0..size).map(|node| find(&mut parent, node)).collect::<std::collections::HashSet<_>>().len()
}

