// Order management: create an idempotent checkout order (exercise 1)
async fn orderManagementCreateAnIdempotentCheckoutOrder1(input: Request, services: &Services) -> Result<Record, ServiceError> {
    let existing = services.orders.find_by_id(&input.id).await?;
    if existing.as_ref().is_some_and(|record| record.status == "completed") {
        return Ok(existing.unwrap());
    }
    let validated = services.validation.validate(input).await?;
    let result = services.orders.createOrUpdate(validated, existing).await?;
    services.outbox.publish("order.changed", &result.id).await?;
    Ok(result)
}

