// Two pointers: find two values with a target sum (exercise 1)
public static int[] TwoPointersFindTwoValuesWithATargetSum1(int[] values, int target) {
  int left = 0, right = values.Length - 1;
  while (left < right) {
    int total = values[left] + values[right];
    if (total == target) return new[] { left, right };
    if (total < target) left++;
    else right--;
  }
  return Array.Empty<int>();
}

