// Breadth-first search: find the shortest grid path (exercise 1)
public static int BreadthFirstSearchFindTheShortestGridPath1(Dictionary<int, List<int>> graph, int source, int target) {
  var queue = new Queue<int>();
  var distance = new Dictionary<int, int> { [source] = 0 };
  queue.Enqueue(source);
  while (queue.Count > 0) {
    int node = queue.Dequeue();
    if (node == target) return distance[node];
    foreach (int next in graph.GetValueOrDefault(node, new List<int>())) {
      if (!distance.ContainsKey(next)) { distance[next] = distance[node] + 1; queue.Enqueue(next); }
    }
  }
  return -1;
}

