// Union find: merge customer accounts (exercise 1)
public static int UnionFindMergeCustomerAccounts1(int size, int[] lefts, int[] rights) {
  var parent = Enumerable.Range(0, size).ToArray();
  int Find(int node) => parent[node] == node ? node : parent[node] = Find(parent[node]);
  for (int index = 0; index < lefts.Length; index++) {
    int a = Find(lefts[index]), b = Find(rights[index]);
    if (a != b) parent[a] = b;
  }
  return parent.Select(Find).Distinct().Count();
}

