// Binary search: find an exact order id (exercise 1)
function binarySearchFindAnExactOrderId1(array $values, int $target): int
{
    $left = 0;
    $right = count($values) - 1;
    while ($left <= $right) {
        $middle = $left + intdiv($right - $left, 2);
        if ($values[$middle] === $target) return $middle;
        if ($values[$middle] < $target) $left = $middle + 1;
        else $right = $middle - 1;
    }
    return -1;
}

