// Sliding window: find the longest unique substring (exercise 1)
function slidingWindowFindTheLongestUniqueSubstring1(string $text): int
{
    $seen = [];
    $start = $best = 0;
    for ($end = 0; $end < strlen($text); $end++) {
        $character = $text[$end];
        if (isset($seen[$character]) && $seen[$character] >= $start) $start = $seen[$character] + 1;
        $seen[$character] = $end;
        $best = max($best, $end - $start + 1);
    }
    return $best;
}

