// Breadth-first search: find the shortest grid path (exercise 1)
function breadthFirstSearchFindTheShortestGridPath1(array $graph, int $source, int $target): int
{
    $queue = [$source];
    $distance = [$source => 0];
    for ($head = 0; $head < count($queue); $head++) {
        $node = $queue[$head];
        if ($node === $target) return $distance[$node];
        foreach ($graph[$node] ?? [] as $next) {
            if (!array_key_exists($next, $distance)) { $distance[$next] = $distance[$node] + 1; $queue[] = $next; }
        }
    }
    return -1;
}

