// Dynamic programming: solve zero-one knapsack (exercise 1)
function dynamicProgrammingSolveZeroOneKnapsack1(array $weights, array $values, int $capacity): int
{
    $dp = array_fill(0, $capacity + 1, 0);
    foreach ($weights as $item => $weight) {
        for ($room = $capacity; $room >= $weight; $room--) {
            $dp[$room] = max($dp[$room], $dp[$room - $weight] + $values[$item]);
        }
    }
    return $dp[$capacity];
}

