// Union find: merge customer accounts (exercise 1)
function unionFindMergeCustomerAccounts1(int $size, array $edges): int
{
    $parent = range(0, $size - 1);
    $find = function (int $node) use (&$parent, &$find): int {
        if ($parent[$node] !== $node) $parent[$node] = $find($parent[$node]);
        return $parent[$node];
    };
    foreach ($edges as [$left, $right]) { $a = $find($left); $b = $find($right); if ($a !== $b) $parent[$a] = $b; }
    return count(array_unique(array_map($find, range(0, $size - 1))));
}

